/// The type ramp, named after the iOS Dynamic Type styles. Fonts are the system font at the
/// matching `Font.TextStyle`, so they scale with Dynamic Type up to AX5; `pointSize` and
/// `lineHeight` are the default ("Large") metrics, for layout math and `@ScaledMetric`.
public enum BFHRTextStyle: String, CaseIterable, Sendable {
    case largeTitle
    case title1
    case title2
    case title3
    case headline
    case body
    case callout
    case subheadline
    case footnote
    case caption1
    case caption2

    /// The Dynamic Type style this token scales with.
    public var textStyle: Font.TextStyle {
        switch self {
        case .largeTitle: .largeTitle
        case .title1: .title
        case .title2: .title2
        case .title3: .title3
        case .headline: .headline
        case .body: .body
        case .callout: .callout
        case .subheadline: .subheadline
        case .footnote: .footnote
        case .caption1: .caption
        case .caption2: .caption2
        }
    }

    public var weight: Font.Weight {
        switch self {
        case .largeTitle: .regular
        case .title1: .regular
        case .title2: .regular
        case .title3: .regular
        case .headline: .semibold
        case .body: .regular
        case .callout: .regular
        case .subheadline: .regular
        case .footnote: .regular
        case .caption1: .regular
        case .caption2: .regular
        }
    }

    /// Weight for bold / emphasized variants (HIG "emphasized").
    public var emphasizedWeight: Font.Weight {
        switch self {
        case .largeTitle: .bold
        case .title1: .bold
        case .title2: .bold
        case .title3: .semibold
        case .headline: .semibold
        case .body: .semibold
        case .callout: .semibold
        case .subheadline: .semibold
        case .footnote: .semibold
        case .caption1: .medium
        case .caption2: .semibold
        }
    }

    /// Default ("Large") size in points; Dynamic Type scales the font from here.
    public var pointSize: CGFloat {
        switch self {
        case .largeTitle: 34
        case .title1: 28
        case .title2: 22
        case .title3: 20
        case .headline: 17
        case .body: 17
        case .callout: 16
        case .subheadline: 15
        case .footnote: 13
        case .caption1: 12
        case .caption2: 11
        }
    }

    /// Default ("Large") line height in points.
    public var lineHeight: CGFloat {
        switch self {
        case .largeTitle: 41
        case .title1: 34
        case .title2: 28
        case .title3: 25
        case .headline: 22
        case .body: 22
        case .callout: 21
        case .subheadline: 20
        case .footnote: 18
        case .caption1: 16
        case .caption2: 13
        }
    }

    public var font: Font { .system(textStyle, weight: weight) }

    public var emphasizedFont: Font { .system(textStyle, weight: emphasizedWeight) }
}

extension Font {
    /// `Text("…").font(.bfhr(.body))`
    public static func bfhr(_ style: BFHRTextStyle, emphasized: Bool = false) -> Font {
        emphasized ? style.emphasizedFont : style.font
    }
}

