/// Haptics by meaning, for `.sensoryFeedback(_:trigger:)`. Only these moments vibrate;
/// dismissals, hides and rejections stay silent.
public enum BFHRHaptic: String, CaseIterable, Sendable {
    case confirm
    case dragTargetChange
    case reveal
    case error

    public var feedback: SensoryFeedback {
        switch self {
        case .confirm: .impact(weight: .light)
        case .dragTargetChange: .selection
        case .reveal: .impact(weight: .light)
        case .error: .error
        }
    }
}
